    shop_title: "Shop",
    shop_sub: "Coeurnoh books and products — like, comment and order.",
    tuto_welcome_title: "Welcome to Coeurnoh Universe",
    tuto_welcome_text: "This guide covers everything the app offers today: the social feed, social media boosting, the wallet, the shop, and all CoeurNoh services. You can reopen it anytime with the help button (question-mark icon) at the top of the screen.",
    tuto_feed_title: "The feed (Home)",
    tuto_feed_sub: "The \"Home\" tab is your social feed, just like other social apps:",
    tuto_feed_step1: "1. Add a story at the top of the screen, or post a photo, video, or text to your feed.",
    tuto_feed_step2: "2. Like, comment on, or share any post — tap it to open it in full.",
    tuto_feed_step3: "3. On a story, tap the author's name (or a viewer's name) to open their profile directly.",
    tuto_feed_step4: "4. The person gets a real notification, even if their phone is closed.",
    tuto_order_title: "Placing a boost order",
    tuto_order_sub: "From the \"Network\" tab at the bottom of the screen:",
    tuto_order_step1: "1. Tap \"View services\".",
    tuto_order_step2: "2. Choose the social network: TikTok, Instagram, YouTube, Facebook...",
    tuto_order_step3: "3. Choose the service: Followers, Likes, Views, Comments...",
    tuto_order_step4: "4. Paste the link to your profile or post.",
    tuto_order_step5: "5. Tap \"Buy\" — delivery starts automatically, no manual action needed.",
    tuto_packages_title: "Packages or à la carte?",
    tuto_packages_sub: "For every service, you have two ways to order:",
    tuto_packages_alacarte_badge: "À la carte",
    tuto_packages_alacarte_text: "You choose the exact quantity yourself (e.g. 350 followers) and the price adjusts automatically.",
    tuto_packages_forfait_badge: "Package (fixed price)",
    tuto_packages_forfait_text: "A ready-made pack (e.g. 200 Followers + 200 Likes + 200 Views) at a great fixed price.",
    tuto_tiers_title: "Standard, Premium or VIP?",
    tuto_tiers_sub: "Every service comes in 3 quality tiers:",
    tuto_tier_standard: "Best value for money — the most affordable option.",
    tuto_tier_premium: "Faster, better retention over time.",
    tuto_tier_vip: "Ultra fast, maximum quality.",
    tuto_monetization_title: "Monetization",
    tuto_monetization_text: "In the \"Network\" tab, the \"Monetization\" button shows the exact criteria each platform (YouTube, TikTok, Facebook...) requires to enable monetization on your account, plus the services best suited to reach them faster.",
    tuto_wallet_intro_title: "Your Wallet",
    tuto_wallet_intro_text: "To place an order, your account needs balance. Go to the \"Wallet\" tab at the bottom of the screen, then pick a payment method: Mobile Money, Crypto, or Card. Your balance and transaction history update in real time as soon as a top-up is confirmed.",
    tuto_mobile_title: "Top up with Mobile Money",
    tuto_mobile_step1: "1. Choose your country, then your carrier (Orange Money, MTN, M-Pesa, Airtel Money...).",
    tuto_mobile_step2: "2. Enter your Mobile Money phone number and the amount to top up.",
    tuto_mobile_step3: "3. Tap \"Send request\".",
    tuto_mobile_step4: "4. Depending on your country, the request is processed automatically within minutes (confirm right on your phone), or reviewed manually by our team if your country isn't automatically covered yet.",
    tuto_mobile_step5: "5. Your balance is credited as soon as the payment is validated.",
    tuto_crypto_title: "Top up with Crypto",
    tuto_crypto_step1: "1. Choose your crypto (USDT, Bitcoin...) and the amount in dollars.",
    tuto_crypto_step2: "2. You're redirected to a secure payment page (Cryptomus) with the exact address and QR code.",
    tuto_crypto_step3: "3. Send the exact amount shown, from your crypto wallet or exchange.",
    tuto_crypto_step4: "4. As soon as it's confirmed on the blockchain, your balance is credited automatically — no manual action on our end.",
    tuto_card_title: "Top up with Card",
    tuto_card_text: "Visa or Mastercard payment is also available in the Wallet, but it's temporarily unavailable right now (being reactivated). In the meantime, use Mobile Money or Crypto.",
    tuto_referral_title: "Referrals",
    tuto_referral_sub: "From the ☰ menu → My space → Referrals:",
    tuto_referral_step1: "1. Copy your personal referral link.",
    tuto_referral_step2: "2. Share it with friends — when they sign up with this link, they're linked to your account.",
    tuto_referral_step3: "3. You automatically earn 5% of every top-up they make, for life, credited to your balance.",
    tuto_shopbuy_title: "Buying in the Shop",
    tuto_shopbuy_step1: "1. Go to \"Shop\" at the bottom of the screen.",
    tuto_shopbuy_step2: "2. Use search or the Books/Products tabs to find what you want.",
    tuto_shopbuy_step3: "3. Tap \"Buy\" — the price is deducted from your balance instantly.",
    tuto_shopbuy_step4: "4. For a book, the download appears right away, and stays accessible forever.",
    tuto_shopbuy_step5: "5. For a product, use the WhatsApp button on the listing to arrange delivery with the seller.",
    tuto_library_note: "A dedicated Library space, for books and ebooks only, is available directly from the Shop.",
    tuto_shopsell_title: "Selling in the Shop",
    tuto_shopsell_sub: "Any account can sell a book or a product. Coeurnoh Universe takes a 10% commission on each sale; you receive 90% directly to your balance, automatically.",
    tuto_shopsell_step1: "1. In \"Shop\", tap \"Sell\".",
    tuto_shopsell_step2: "2. Fill in the title, description and price.",
    tuto_shopsell_step3: "3. Add your photo link (see the next step to learn how to get one).",
    tuto_shopsell_step4: "4. For a book, also add the PDF link. For a product, add your WhatsApp number.",
    tuto_shopsell_step5: "5. Publish — your item appears immediately. Tap \"Seller\" to track your sales and request a withdrawal.",
    tuto_links_title: "Getting a photo or PDF link",
    tuto_links_sub: "These links are free and don't require an account:",
    tuto_links_image: "Go to postimages.org → \"Choose images\" → select your photo → once uploaded, copy the \"Direct link\" (not the other formats).",
    tuto_links_pdf: "Upload your PDF to Google Drive → 3-dot menu → \"Share\" → choose \"Anyone with the link\" → copy the link.",
    tuto_menu_title: "The ☰ menu",
    tuto_menu_sub: "In the bottom right, the \"Menu\" button holds everything else:",
    tuto_menu_myspace_badge: "My space",
    tuto_menu_myspace_text: "Your profile, saved posts, followers/following, referrals, and your orders.",
    tuto_menu_settings_badge: "Settings",
    tuto_menu_settings_text: "Account, security, blocked accounts, notifications, appearance, and language.",
    tuto_services_title: "CoeurNoh Services",
    tuto_services_sub: "Still in the ☰ menu, the \"CoeurNoh Services\" category gives access to:",
    tuto_services_text: "Find a professional, Build your site, CoeurNoh Business, Invoices & Receipts, Jobs & Freelance, CoeurNoh Academy, Real Estate, CoeurNoh Travel, Online Booking, Nearby, Events, Contests & Rewards, and Alerts. New services are added here regularly.",
    tuto_install_title: "Install the app",
    tuto_install_text: "Still using Coeurnoh Universe in your browser? Tap the \"Install app\" button at the top of the screen to add it as a real app, with an icon on your home screen — faster, and notifications arrive more reliably.",
    tuto_finish_title: "Ready for takeoff!",
    tuto_finish_text: "You now know how to use everything. Still have a question? The WhatsApp button in the bottom right puts you in direct contact with us, anytime.",
    tuto_finish_cta: "Got it, let's start →",
    tuto_next: "Next →",
    tuto_prev: "← Previous",

