    tuto_welcome_title: "Bienvenido a Coeurnoh Universe",
    tuto_welcome_text: "Esta guía recorre todo lo que la aplicación ofrece hoy: el muro social, el boost de redes sociales, el monedero, la tienda y todos los servicios CoeurNoh. Puedes volver a abrirla en cualquier momento con el botón de ayuda (icono «?») en la parte superior de la pantalla.",
    tuto_feed_title: "El muro social (Inicio)",
    tuto_feed_sub: "La pestaña «Inicio» es tu muro social, como en las redes:",
    tuto_feed_step1: "1. Añade una historia en la parte superior de la pantalla, o publica una foto, un video o un texto en tu muro.",
    tuto_feed_step2: "2. Dale like, comenta o comparte cualquier publicación — tócala para abrirla por completo.",
    tuto_feed_step3: "3. En una historia, toca el nombre del autor (o de alguien que la haya visto) para abrir directamente su perfil.",
    tuto_feed_step4: "4. La persona en cuestión recibe una notificación real, incluso con el teléfono cerrado.",
    tuto_order_title: "Pedir un boost",
    tuto_order_sub: "Desde la pestaña «Red» en la parte inferior de la pantalla:",
    tuto_order_step1: "1. Toca «Ver los servicios».",
    tuto_order_step2: "2. Elige la red social: TikTok, Instagram, YouTube, Facebook...",
    tuto_order_step3: "3. Elige el servicio: Seguidores, Likes, Vistas, Comentarios...",
    tuto_order_step4: "4. Pega el enlace de tu perfil o de tu publicación.",
    tuto_order_step5: "5. Toca «Comprar» — la entrega empieza automáticamente, sin intervención manual.",
    tuto_packages_title: "¿Forfait o a la carta?",
    tuto_packages_sub: "En cada servicio, tienes dos formas de pedir:",
    tuto_packages_alacarte_badge: "A la carta",
    tuto_packages_alacarte_text: "Eliges tú mismo la cantidad exacta (ej: 350 seguidores) y el precio se ajusta automáticamente.",
    tuto_packages_forfait_badge: "Forfait (precio fijo)",
    tuto_packages_forfait_text: "Un pack ya listo (ej: 200 Seguidores + 200 Likes + 200 Vistas) a un precio fijo ventajoso.",
    tuto_tiers_title: "¿Standard, Premium o VIP?",
    tuto_tiers_sub: "Cada servicio ofrece 3 niveles de calidad:",
    tuto_tier_standard: "Buena relación calidad-precio — la opción más económica.",
    tuto_tier_premium: "Más rápido, mejor retención en el tiempo.",
    tuto_tier_vip: "Ultra rápido, calidad máxima.",
    tuto_monetization_title: "La Monetización",
    tuto_monetization_text: "En la pestaña «Red», el botón «Monetización» te muestra los criterios exactos que exige cada plataforma (YouTube, TikTok, Facebook...) para activar la monetización de tu cuenta, además de los servicios adaptados para alcanzarlos más rápido.",
    tuto_wallet_intro_title: "El Monedero",
    tuto_wallet_intro_text: "Para pedir, tu cuenta debe tener saldo. Ve a la pestaña «Monedero» en la parte inferior de la pantalla, luego elige un método de pago: Mobile Money, Crypto o Tarjeta. Tu saldo y tu historial de transacciones se actualizan en tiempo real en cuanto se confirma una recarga.",
    tuto_mobile_title: "Recargar por Mobile Money",
    tuto_mobile_step1: "1. Elige tu país, luego tu operador (Orange Money, MTN, M-Pesa, Airtel Money...).",
    tuto_mobile_step2: "2. Introduce tu número de teléfono Mobile Money y el monto a recargar.",
    tuto_mobile_step3: "3. Toca «Enviar la solicitud».",
    tuto_mobile_step4: "4. Según tu país, la solicitud se procesa automáticamente en pocos minutos (confirma directamente en tu teléfono) o se verifica manualmente por nuestro equipo si tu país aún no está cubierto automáticamente.",
    tuto_mobile_step5: "5. Tu saldo se acredita en cuanto se valida el pago.",
    tuto_crypto_title: "Recargar en Crypto",
    tuto_crypto_step1: "1. Elige tu cripto (USDT, Bitcoin...) y el monto en dólares.",
    tuto_crypto_step2: "2. Serás redirigido a una página de pago segura (Cryptomus) con la dirección y el código QR exactos.",
    tuto_crypto_step3: "3. Envía el monto exacto mostrado, desde tu monedero cripto o tu exchange.",
    tuto_crypto_step4: "4. En cuanto se confirme en la blockchain, tu saldo se acredita automáticamente — ninguna acción manual de nuestra parte.",
    tuto_card_title: "Recargar por Tarjeta",
    tuto_card_text: "El pago con tarjeta Visa o Mastercard también existe en el Monedero, pero está momentáneamente indisponible (en proceso de reactivación). Mientras tanto, usa Mobile Money o Crypto.",
    tuto_referral_title: "El Padrinazgo",
    tuto_referral_sub: "Desde el menú ☰ → Mi espacio → Padrinazgo:",
    tuto_referral_step1: "1. Copia tu enlace de padrinazgo personal.",
    tuto_referral_step2: "2. Compártelo con tus amigos — cuando se registren con ese enlace, quedan vinculados a tu cuenta.",
    tuto_referral_step3: "3. Ganas automáticamente el 5% de cada una de sus recargas, de por vida, acreditado en tu saldo.",
    tuto_shopbuy_title: "Comprar en la Tienda",
    tuto_shopbuy_step1: "1. Ve a «Tienda» en la parte inferior de la pantalla.",
    tuto_shopbuy_step2: "2. Usa la búsqueda o las pestañas Libros/Productos para encontrar lo que quieres.",
    tuto_shopbuy_step3: "3. Toca «Pedir» — el precio se descuenta de tu saldo al instante.",
    tuto_shopbuy_step4: "4. Para un libro, la descarga aparece de inmediato, y queda accesible para siempre.",
    tuto_shopbuy_step5: "5. Para un producto, usa el botón de WhatsApp en el artículo para coordinar la entrega con el vendedor.",
    tuto_library_note: "Un espacio Biblioteca dedicado, solo para libros y ebooks, es accesible directamente desde la Tienda.",
    tuto_shopsell_title: "Vender en la Tienda",
    tuto_shopsell_sub: "Cualquier cuenta puede vender un libro o un producto. Coeurnoh Universe cobra una comisión del 10% en cada venta; recibes el 90% directamente en tu saldo, automáticamente.",
    tuto_shopsell_step1: "1. En «Tienda», toca «Vender».",
    tuto_shopsell_step2: "2. Completa el título, la descripción y el precio.",
    tuto_shopsell_step3: "3. Añade el enlace de tu foto (ve el siguiente paso para saber cómo obtenerlo).",
    tuto_shopsell_step4: "4. Para un libro, añade también el enlace del PDF. Para un producto, añade tu número de WhatsApp.",
    tuto_shopsell_step5: "5. Publica — tu artículo aparece de inmediato. Toca «Vendedor» para seguir tus ventas y solicitar un retiro.",
    tuto_links_title: "Obtener un enlace de foto o PDF",
    tuto_links_sub: "Estos enlaces son gratuitos y no requieren cuenta:",
    tuto_links_image: "Ve a postimages.org → «Choose images» → selecciona tu foto → una vez subida, copia el enlace «Direct link» (no los otros formatos).",
    tuto_links_pdf: "Sube tu PDF a Google Drive → menú de 3 puntos → «Compartir» → elige «Cualquier persona con el enlace» → copia el enlace.",
    tuto_menu_title: "El menú ☰",
    tuto_menu_sub: "Abajo a la derecha, el botón «Menú» agrupa todo lo demás:",
    tuto_menu_myspace_badge: "Mi espacio",
    tuto_menu_myspace_text: "Tu perfil, tus publicaciones guardadas, tus seguidores/seguidos, tu padrinazgo y tus pedidos.",
    tuto_menu_settings_badge: "Configuración",
    tuto_menu_settings_text: "Cuenta, seguridad, cuentas bloqueadas, notificaciones, apariencia e idioma.",
    tuto_services_title: "Servicios CoeurNoh",
    tuto_services_sub: "Siempre en el menú ☰, la categoría «Servicios CoeurNoh» da acceso a:",
    tuto_services_text: "Encontrar un profesional, Crea tu sitio, CoeurNoh Business, Facturas y Recibos, Empleo y Freelance, CoeurNoh Academy, Inmobiliaria, CoeurNoh Travel, Reserva en línea, Cerca de ti, Eventos, Concursos y Premios, y las Alertas. Se añaden nuevos servicios regularmente aquí.",
    tuto_install_title: "Instalar la aplicación",
    tuto_install_text: "¿Sigues usando Coeurnoh Universe en tu navegador? Toca el botón «Instalar app» en la parte superior de la pantalla para añadirla como una aplicación real, con un icono en tu pantalla de inicio — más rápida, y las notificaciones llegan mejor.",
    tuto_finish_title: "¡Listo para despegar!",
    tuto_finish_text: "Ya sabes usarlo todo. ¿Queda alguna duda? El botón de WhatsApp abajo a la derecha te pone en contacto directo con nosotros, en cualquier momento.",
    tuto_finish_cta: "Entendido, empezar →",
