    tuto_welcome_text: "Questa guida illustra tutto ciò che l'app offre oggi: il feed social, il boost dei social network, il portafoglio, il negozio e tutti i servizi CoeurNoh. Puoi riaprirla in qualsiasi momento con il pulsante di aiuto (icona «?») in alto sullo schermo.",
    tuto_feed_title: "Il feed (Home)",
    tuto_feed_sub: "La scheda «Home» è il tuo feed social, come sui social network:",
    tuto_feed_step1: "1. Aggiungi una storia in alto sullo schermo, oppure pubblica una foto, un video o un testo sul tuo feed.",
    tuto_feed_step2: "2. Metti mi piace, commenta o condividi qualsiasi post — toccalo per aprirlo per intero.",
    tuto_feed_step3: "3. Su una storia, tocca il nome dell'autore (o di chi l'ha vista) per aprire direttamente il suo profilo.",
    tuto_feed_step4: "4. La persona interessata riceve una vera notifica, anche a telefono spento.",
    tuto_order_title: "Ordinare un boost",
    tuto_order_sub: "Dalla scheda «Rete» in basso sullo schermo:",
    tuto_order_step1: "1. Tocca «Vedi i servizi».",
    tuto_order_step2: "2. Scegli il social network: TikTok, Instagram, YouTube, Facebook...",
    tuto_order_step3: "3. Scegli il servizio: Follower, Mi piace, Visualizzazioni, Commenti...",
    tuto_order_step4: "4. Incolla il link del tuo profilo o del tuo post.",
    tuto_order_step5: "5. Tocca «Acquista» — la consegna parte automaticamente, senza intervento manuale.",
    tuto_packages_title: "Pacchetto o à la carte?",
    tuto_packages_sub: "Per ogni servizio, hai due modi di ordinare:",
    tuto_packages_alacarte_badge: "À la carte",
    tuto_packages_alacarte_text: "Scegli tu stesso la quantità esatta (es: 350 follower) e il prezzo si adatta automaticamente.",
    tuto_packages_forfait_badge: "Pacchetto (prezzo fisso)",
    tuto_packages_forfait_text: "Un pack già pronto (es: 200 Follower + 200 Mi piace + 200 Visualizzazioni) a un prezzo fisso vantaggioso.",
    tuto_tiers_title: "Standard, Premium o VIP?",
    tuto_tiers_sub: "Ogni servizio propone 3 livelli di qualità:",
    tuto_tier_standard: "Ottimo rapporto qualità-prezzo — la scelta più economica.",
    tuto_tier_premium: "Più veloce, migliore ritenzione nel tempo.",
    tuto_tier_vip: "Ultra veloce, qualità massima.",
    tuto_monetization_title: "La Monetizzazione",
    tuto_monetization_text: "Nella scheda «Rete», il pulsante «Monetizzazione» mostra i criteri esatti richiesti da ciascuna piattaforma (YouTube, TikTok, Facebook...) per attivare la monetizzazione del tuo account, oltre ai servizi adatti per raggiungerli più rapidamente.",
    tuto_wallet_intro_title: "Il Portafoglio",
    tuto_wallet_intro_text: "Per ordinare, il tuo account deve avere saldo. Vai nella scheda «Portafoglio» in basso sullo schermo, poi scegli un metodo di pagamento: Mobile Money, Crypto o Carta. Il tuo saldo e lo storico delle transazioni si aggiornano in tempo reale non appena una ricarica è confermata.",
    tuto_mobile_title: "Ricaricare con Mobile Money",
    tuto_mobile_step1: "1. Scegli il tuo paese, poi il tuo operatore (Orange Money, MTN, M-Pesa, Airtel Money...).",
    tuto_mobile_step2: "2. Inserisci il tuo numero di telefono Mobile Money e l'importo da ricaricare.",
    tuto_mobile_step3: "3. Tocca «Invia la richiesta».",
    tuto_mobile_step4: "4. A seconda del paese, la richiesta viene elaborata automaticamente in pochi minuti (conferma direttamente sul telefono) oppure verificata manualmente dal nostro team se il tuo paese non è ancora coperto automaticamente.",
    tuto_mobile_step5: "5. Il tuo saldo viene accreditato appena il pagamento è convalidato.",
    tuto_crypto_title: "Ricaricare in Crypto",
    tuto_crypto_step1: "1. Scegli la tua crypto (USDT, Bitcoin...) e l'importo in dollari.",
    tuto_crypto_step2: "2. Vieni reindirizzato a una pagina di pagamento sicura (Cryptomus) con l'indirizzo e il codice QR esatti.",
    tuto_crypto_step3: "3. Invia l'importo esatto mostrato, dal tuo wallet crypto o dal tuo exchange.",
    tuto_crypto_step4: "4. Appena confermato sulla blockchain, il tuo saldo viene accreditato automaticamente — nessuna azione manuale da parte nostra.",
    tuto_card_title: "Ricaricare con Carta",
    tuto_card_text: "Il pagamento con carta Visa o Mastercard esiste anche nel Portafoglio, ma al momento è temporaneamente non disponibile (in fase di riattivazione). Nel frattempo, usa Mobile Money o Crypto.",
    tuto_referral_title: "Il Referral",
    tuto_referral_sub: "Dal menu ☰ → Il mio spazio → Referral:",
    tuto_referral_step1: "1. Copia il tuo link di referral personale.",
    tuto_referral_step2: "2. Condividilo con gli amici — quando si iscrivono con quel link, vengono collegati al tuo account.",
    tuto_referral_step3: "3. Guadagni automaticamente il 5% di ogni loro ricarica, a vita, accreditato sul tuo saldo.",
    tuto_shopbuy_title: "Acquistare nel Negozio",
    tuto_shopbuy_step1: "1. Vai su «Negozio» in basso sullo schermo.",
    tuto_shopbuy_step2: "2. Usa la ricerca o le schede Libri/Prodotti per trovare ciò che vuoi.",
    tuto_shopbuy_step3: "3. Tocca «Ordina» — il prezzo viene addebitato dal tuo saldo istantaneamente.",
    tuto_shopbuy_step4: "4. Per un libro, il download appare subito e resta accessibile per sempre.",
    tuto_shopbuy_step5: "5. Per un prodotto, usa il pulsante WhatsApp sull'articolo per organizzare la consegna con il venditore.",
    tuto_library_note: "Uno spazio Biblioteca dedicato, solo per libri ed ebook, è accessibile direttamente dal Negozio.",
    tuto_shopsell_title: "Vendere nel Negozio",
    tuto_shopsell_sub: "Qualsiasi account può vendere un libro o un prodotto. Coeurnoh Universe trattiene una commissione del 10% su ogni vendita; ricevi il 90% direttamente sul tuo saldo, automaticamente.",
    tuto_shopsell_step1: "1. In «Negozio», tocca «Vendi».",
    tuto_shopsell_step2: "2. Compila titolo, descrizione e prezzo.",
    tuto_shopsell_step3: "3. Aggiungi il link della tua foto (vedi il passaggio successivo per sapere come ottenerlo).",
    tuto_shopsell_step4: "4. Per un libro, aggiungi anche il link del PDF. Per un prodotto, aggiungi il tuo numero WhatsApp.",
    tuto_shopsell_step5: "5. Pubblica — il tuo articolo appare immediatamente. Tocca «Venditore» per seguire le tue vendite e richiedere un prelievo.",
    tuto_links_title: "Ottenere un link foto o PDF",
    tuto_links_sub: "Questi link sono gratuiti e non richiedono un account:",
    tuto_links_image: "Vai su postimages.org → «Choose images» → seleziona la tua foto → una volta caricata, copia il link «Direct link» (non gli altri formati).",
    tuto_links_pdf: "Carica il tuo PDF su Google Drive → menu a 3 puntini → «Condividi» → scegli «Chiunque abbia il link» → copia il link.",
    tuto_menu_title: "Il menu ☰",
    tuto_menu_sub: "In basso a destra, il pulsante «Menu» raggruppa tutto il resto:",
    tuto_menu_myspace_badge: "Il mio spazio",
    tuto_menu_myspace_text: "Il tuo profilo, i post salvati, i tuoi follower/seguiti, il tuo referral e i tuoi ordini.",
    tuto_menu_settings_badge: "Impostazioni",
    tuto_menu_settings_text: "Account, sicurezza, account bloccati, notifiche, aspetto e lingua.",
    tuto_services_title: "Servizi CoeurNoh",
    tuto_services_sub: "Sempre nel menu ☰, la categoria «Servizi CoeurNoh» dà accesso a:",
    tuto_services_text: "Trovare un professionista, Crea il tuo sito, CoeurNoh Business, Fatture e Ricevute, Lavoro e Freelance, CoeurNoh Academy, Immobiliare, CoeurNoh Travel, Prenotazione online, Vicino a te, Eventi, Concorsi e Premi, e gli Avvisi. Nuovi servizi si aggiungono regolarmente qui.",
    tuto_install_title: "Installare l'applicazione",
    tuto_install_text: "Usi ancora Coeurnoh Universe nel browser? Tocca il pulsante «Installa app» in alto sullo schermo per aggiungerla come una vera app, con un'icona sulla schermata home — più veloce, e le notifiche arrivano meglio.",
    tuto_finish_title: "Pronto per il decollo!",
    tuto_finish_text: "Ora sai usare tutto. Hai ancora un dubbio? Il pulsante WhatsApp in basso a destra ti mette in contatto diretto con noi, in qualsiasi momento.",
    tuto_finish_cta: "Capito, iniziamo →",
    tuto_next: "Avanti →",
    tuto_prev: "← Indietro",
