    tuto_welcome_title: "Bem-vindo ao Coeurnoh Universe",
    tuto_welcome_text: "Este guia percorre tudo o que o aplicativo oferece hoje: o feed social, o boost de redes sociais, a carteira, a loja e todos os serviços CoeurNoh. Podes reabri-lo a qualquer momento com o botão de ajuda (ícone «?») no topo da tela.",
    tuto_feed_title: "O feed (Início)",
    tuto_feed_sub: "A aba «Início» é o teu feed social, como nas redes:",
    tuto_feed_step1: "1. Adiciona um story no topo da tela, ou publica uma foto, vídeo ou texto no teu feed.",
    tuto_feed_step2: "2. Curte, comenta ou compartilha qualquer publicação — toca nela para abri-la por inteiro.",
    tuto_feed_step3: "3. Num story, toca no nome do autor (ou de alguém que o tenha visto) para abrir diretamente o perfil dessa pessoa.",
    tuto_feed_step4: "4. A pessoa em questão recebe uma notificação real, mesmo com o telefone fechado.",
    tuto_order_title: "Pedir um boost",
    tuto_order_sub: "Na aba «Rede» na parte inferior da tela:",
    tuto_order_step1: "1. Toca em «Ver os serviços».",
    tuto_order_step2: "2. Escolhe a rede social: TikTok, Instagram, YouTube, Facebook...",
    tuto_order_step3: "3. Escolhe o serviço: Seguidores, Curtidas, Visualizações, Comentários...",
    tuto_order_step4: "4. Cola o link do teu perfil ou da tua publicação.",
    tuto_order_step5: "5. Toca em «Comprar» — a entrega começa automaticamente, sem intervenção manual.",
    tuto_packages_title: "Pacote ou à la carte?",
    tuto_packages_sub: "Em cada serviço, tens duas formas de pedir:",
    tuto_packages_alacarte_badge: "À la carte",
    tuto_packages_alacarte_text: "Escolhes tu mesmo a quantidade exata (ex: 350 seguidores) e o preço se ajusta automaticamente.",
    tuto_packages_forfait_badge: "Pacote (preço fixo)",
    tuto_packages_forfait_text: "Um pacote pronto (ex: 200 Seguidores + 200 Curtidas + 200 Visualizações) a um preço fixo vantajoso.",
    tuto_tiers_title: "Standard, Premium ou VIP?",
    tuto_tiers_sub: "Cada serviço oferece 3 níveis de qualidade:",
    tuto_tier_standard: "Boa relação custo-benefício — a opção mais econômica.",
    tuto_tier_premium: "Mais rápido, melhor retenção ao longo do tempo.",
    tuto_tier_vip: "Ultra rápido, qualidade máxima.",
    tuto_monetization_title: "A Monetização",
    tuto_monetization_text: "Na aba «Rede», o botão «Monetização» mostra os critérios exatos que cada plataforma (YouTube, TikTok, Facebook...) exige para ativar a monetização da tua conta, além dos serviços adequados para alcançá-los mais rápido.",
    tuto_wallet_intro_title: "A Carteira",
    tuto_wallet_intro_text: "Para pedir, a tua conta precisa ter saldo. Vai na aba «Carteira» na parte inferior da tela, depois escolhe um método de pagamento: Mobile Money, Cripto ou Cartão. Teu saldo e o histórico de transações são atualizados em tempo real assim que uma recarga é confirmada.",
    tuto_mobile_title: "Recarregar por Mobile Money",
    tuto_mobile_step1: "1. Escolhe teu país, depois tua operadora (Orange Money, MTN, M-Pesa, Airtel Money...).",
    tuto_mobile_step2: "2. Digita teu número de telefone Mobile Money e o valor a recarregar.",
    tuto_mobile_step3: "3. Toca em «Enviar o pedido».",
    tuto_mobile_step4: "4. Dependendo do teu país, o pedido é processado automaticamente em poucos minutos (confirma diretamente no teu telefone) ou verificado manualmente pela nossa equipe se o teu país ainda não estiver coberto automaticamente.",
    tuto_mobile_step5: "5. Teu saldo é creditado assim que o pagamento é validado.",
    tuto_crypto_title: "Recarregar em Cripto",
    tuto_crypto_step1: "1. Escolhe tua cripto (USDT, Bitcoin...) e o valor em dólares.",
    tuto_crypto_step2: "2. És redirecionado para uma página de pagamento segura (Cryptomus) com o endereço e o código QR exatos.",
    tuto_crypto_step3: "3. Envia o valor exato exibido, da tua carteira cripto ou da tua exchange.",
    tuto_crypto_step4: "4. Assim que confirmado na blockchain, teu saldo é creditado automaticamente — nenhuma ação manual da nossa parte.",
    tuto_card_title: "Recarregar por Cartão",
    tuto_card_text: "O pagamento por cartão Visa ou Mastercard também existe na Carteira, mas está momentaneamente indisponível (em processo de reativação). Enquanto isso, usa Mobile Money ou Cripto.",
    tuto_referral_title: "O Programa de Indicação",
    tuto_referral_sub: "No menu ☰ → Meu espaço → Indicação:",
    tuto_referral_step1: "1. Copia teu link de indicação pessoal.",
    tuto_referral_step2: "2. Compartilha com teus amigos — quando eles se cadastrarem com esse link, ficam vinculados à tua conta.",
    tuto_referral_step3: "3. Ganhas automaticamente 5% de cada recarga deles, para sempre, creditado no teu saldo.",
    tuto_shopbuy_title: "Comprar na Loja",
    tuto_shopbuy_step1: "1. Vai em «Loja» na parte inferior da tela.",
    tuto_shopbuy_step2: "2. Usa a busca ou as abas Livros/Produtos para encontrar o que queres.",
    tuto_shopbuy_step3: "3. Toca em «Pedir» — o preço é debitado do teu saldo instantaneamente.",
    tuto_shopbuy_step4: "4. Para um livro, o download aparece na hora, e permanece acessível para sempre.",
    tuto_shopbuy_step5: "5. Para um produto, usa o botão do WhatsApp no anúncio para combinar a entrega com o vendedor.",
    tuto_library_note: "Um espaço Biblioteca dedicado, apenas para livros e ebooks, está acessível diretamente pela Loja.",
    tuto_shopsell_title: "Vender na Loja",
    tuto_shopsell_sub: "Qualquer conta pode vender um livro ou um produto. O Coeurnoh Universe cobra uma comissão de 10% em cada venda; recebes 90% diretamente no teu saldo, automaticamente.",
    tuto_shopsell_step1: "1. Na «Loja», toca em «Vender».",
    tuto_shopsell_step2: "2. Preenche o título, a descrição e o preço.",
    tuto_shopsell_step3: "3. Adiciona o link da tua foto (vê o próximo passo para saber como obtê-lo).",
    tuto_shopsell_step4: "4. Para um livro, adiciona também o link do PDF. Para um produto, adiciona teu número de WhatsApp.",
    tuto_shopsell_step5: "5. Publica — teu anúncio aparece imediatamente. Toca em «Vendedor» para acompanhar tuas vendas e solicitar um saque.",
    tuto_links_title: "Obter um link de foto ou PDF",
    tuto_links_sub: "Esses links são gratuitos e não exigem conta:",
